package site.hsu.hub;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;import site.hsu.hub.identity.adapter.out.persistence.*;import java.time.Instant;import java.util.UUID;import static org.hamcrest.Matchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest@AutoConfigureMockMvc@Transactional class SecuritySessionTest{
 @Autowired MockMvc mvc;@Autowired UserRepository users;@Autowired PasswordEncoder encoder;
 @Test void passwordUsesArgon2idAndLoginSetsHostOnlySecureCookie()throws Exception{String email=UUID.randomUUID()+"@hansung.ac.kr";var user=new UserEntity(email,encoder.encode("password1234"));user.verify(Instant.now());users.save(user);assertThat(user.passwordHash()).startsWith("$argon2id$");mvc.perform(post("/api/v1/auth/login").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"password1234\"}")).andExpect(status().isOk()).andExpect(header().string("Set-Cookie",allOf(containsString("__Host-HSU_SESSION="),containsString("Path=/"),containsString("Secure"),containsString("HttpOnly"),containsString("SameSite=Lax"),not(containsString("Domain=")))));}
}
